create table public.nexus_biz_items(owner_id uuid not null default auth.uid() references auth.users(id), venue text not null check(venue in ('NOMAD','Artist')), id uuid not null default gen_random_uuid(), sku text not null check(length(sku) between 1 and 80), name text not null check(length(name) between 1 and 200), unit text not null check(unit in ('kom','kg','L')), purchase_price numeric(14,4) not null check(purchase_price>=0), primary key(owner_id,venue,id), unique(owner_id,venue,sku));
alter table public.nexus_biz_items enable row level security;
revoke all on public.nexus_biz_items from public, anon, authenticated;
grant select,insert,update,delete on public.nexus_biz_items to authenticated;
create policy owner_select on public.nexus_biz_items for select to authenticated using ((select auth.uid())=owner_id and coalesce((select auth.jwt())->'app_metadata'->>'nexus_ai_access','false')='true' and coalesce((select auth.jwt())->>'is_anonymous','false')='false');
create policy owner_insert on public.nexus_biz_items for insert to authenticated with check ((select auth.uid())=owner_id and coalesce((select auth.jwt())->'app_metadata'->>'nexus_ai_access','false')='true' and coalesce((select auth.jwt())->>'is_anonymous','false')='false');
create policy owner_update on public.nexus_biz_items for update to authenticated using ((select auth.uid())=owner_id and coalesce((select auth.jwt())->'app_metadata'->>'nexus_ai_access','false')='true' and coalesce((select auth.jwt())->>'is_anonymous','false')='false') with check ((select auth.uid())=owner_id and coalesce((select auth.jwt())->'app_metadata'->>'nexus_ai_access','false')='true' and coalesce((select auth.jwt())->>'is_anonymous','false')='false');
create policy owner_delete on public.nexus_biz_items for delete to authenticated using ((select auth.uid())=owner_id and coalesce((select auth.jwt())->'app_metadata'->>'nexus_ai_access','false')='true' and coalesce((select auth.jwt())->>'is_anonymous','false')='false');
